<script>
(() => {
const form=document.querySelector('.sales-editor'),branch=document.getElementById('branch'),lines=document.getElementById('lines'),issued=document.getElementById('issued'),due=document.getElementById('due'),terms=document.getElementById('payment-terms'),agent=document.getElementById('sales-agent'),status=document.getElementById('catalogue-status');
let catalogue=@json($catalogue),generation=0,previewGeneration=0,timer,dirty=false;
const option=(label,value)=>{const node=document.createElement('option');node.textContent=label;node.value=value;return node;};
const fill=(select,rows,placeholder,label)=>{const current=select.dataset.selected??select.value;delete select.dataset.selected;select.replaceChildren(option(placeholder,''));rows.forEach(row=>select.append(option(label(row),row.id)));select.value=rows.some(row=>String(row.id)===String(current))?current:'';};
const fillLines=()=>{const taxes=(catalogue?.taxes??[]).filter(tax=>tax.effective_from<=issued.value&&(!tax.effective_until||tax.effective_until>=issued.value));lines.querySelectorAll('[data-tax]').forEach(select=>fill(select,taxes,'Choose tax',row=>row.label+' ('+(row.basis_points/100)+'%)'));lines.querySelectorAll('[data-service]').forEach(select=>fill(select,catalogue?.services??[],'Custom service',row=>row.name));};
const render=()=>{document.getElementById('invoice-currency').textContent=catalogue?.currency??'';fill(agent,catalogue?.agents??[],'Unassigned',row=>row.name);fillLines();status.textContent=!branch.value?'Choose a branch.':!catalogue?'Settings could not be loaded.':!catalogue.profile?'Branch billing profile needs configuration before issuing.':!catalogue.taxes.length?'No active tax categories. Configure taxes in Sales settings.':'';};
branch.addEventListener('change',()=>{lines.querySelectorAll('[name$="[unit_price]"]').forEach(input=>input.value='');});
branch.addEventListener('change',async()=>{const version=++generation;catalogue=null;render();schedule();if(!branch.value)return;status.textContent='Loading services and taxes...';try{const url=new URL(@json(route('billing.catalogue')));url.searchParams.set('branch_id',branch.value);const response=await fetch(url,{headers:{Accept:'application/json'}});if(!response.ok)throw Error();const body=await response.json();if(version!==generation)return;catalogue=body;render();schedule();}catch(error){if(version===generation){status.textContent='Could not load branch settings. ';const retry=document.createElement('button');retry.type='button';retry.className='btn btn-outline-primary btn-sm';retry.textContent='Retry';retry.onclick=()=>branch.dispatchEvent(new Event('change'));status.append(retry);}}});
lines.addEventListener('change',event=>{const row=event.target.closest('.sales-form-row');if(!row)return;if(event.target.matches('[data-service]')){const service=catalogue?.services.find(service=>String(service.id)===event.target.value);if(service){const values={description:service.name,unit:service.unit,unit_price:(service.price_minor/100).toFixed(2),tax_id:String(service.tax_id),tax_mode:service.tax_mode};Object.entries(values).forEach(([field,value])=>{row.querySelector('[name$="['+field+']"]').value=value;});}}const tax=catalogue?.taxes.find(tax=>String(tax.id)===row.querySelector('[data-tax]').value);row.querySelector('[name$="[tax_percent]"]').value=tax?(tax.basis_points/100).toFixed(2):'0';schedule();});
const dates=()=>{if(terms.value==='custom')return;const date=new Date(issued.value+'T12:00:00Z');if(Number.isNaN(date.getTime()))return;date.setUTCDate(date.getUTCDate()+(terms.value==='receipt'?0:Number(terms.value.slice(3))));due.value=date.toISOString().slice(0,10);};
terms.addEventListener('change',dates);due.addEventListener('change',()=>terms.value='custom');issued.addEventListener('change',()=>{dates();fillLines();schedule();});
async function preview(version){const notice=document.getElementById('totals-status'),totals=document.getElementById('live-totals');notice.textContent='Calculating...';try{const payload=new FormData(form);payload.delete('_method');const response=await fetch(@json(route('billing.preview')),{method:'POST',headers:{Accept:'application/json'},body:payload});const body=await response.json();if(version!==previewGeneration)return;if(!response.ok){totals.hidden=true;notice.textContent=body.errors?Object.values(body.errors).flat()[0]:'Could not calculate the total. Please try again.';return;}notice.textContent='';totals.hidden=false;totals.querySelectorAll('[data-total]').forEach(node=>node.textContent=body.currency+' '+(body[node.dataset.total]/100).toLocaleString('en',{minimumFractionDigits:2,maximumFractionDigits:2}));}catch(error){if(version===previewGeneration){totals.hidden=true;notice.textContent='Could not calculate the total. Edit a field to try again.';}}}
function schedule(){clearTimeout(timer);const version=++previewGeneration;document.getElementById('live-totals').hidden=true;if(!branch.value){document.getElementById('totals-status').textContent='Choose a branch to calculate the total.';return;}timer=setTimeout(()=>preview(version),450);}
form.addEventListener('input',()=>{dirty=true;schedule();});form.addEventListener('change',()=>{dirty=true;schedule();});lines.addEventListener('click',event=>{if(event.target.closest('[data-remove]')){dirty=true;schedule();}});
window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
form.addEventListener('submit',()=>{dirty=false;form.querySelector('button[type="submit"]').disabled=true;});window.addEventListener('pageshow',()=>form.querySelector('button[type="submit"]').disabled=false);
render();
})();
</script>
